 'base64-encoder':()=>simple(s=>btoa(unescape(encodeURIComponent(s)))),'base64-decoder':()=>simple(s=>decodeURIComponent(escape(atob(s)))),'url-encoder':()=>simple(s=>encodeURIComponent(s)),'url-decoder':()=>simple(s=>decodeURIComponent(s)),
 'html-encoder':()=>simple(s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))),'html-decoder':()=>simple(s=>{const t=document.createElement('textarea');t.innerHTML=s;return t.value}),
 'uuid-generator':()=>{A.innerHTML='<h2>UUID Generator</h2><button class="btn" id="go">Generate</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=crypto.randomUUID()},
 'random-number-generator':()=>{A.innerHTML='<h2>Random Number Generator</h2><div class="row"><input id="a" class="input" type="number" value="1"><input id="b" class="input" type="number" value="100"></div><button class="btn" id="go">Generate</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=Math.floor(Math.random()*(+$('#b').value-+$('#a').value+1)) + +$('#a').value},
 'unix-timestamp':()=>{A.innerHTML='<h2>Unix Timestamp</h2><button class="btn" id="go">Get Timestamp</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=Math.floor(Date.now()/1000)},
 'timestamp-converter':()=>{A.innerHTML='<h2>Timestamp Converter</h2><input id="v" class="input" type="number" placeholder="Unix timestamp"><button class="btn" id="go">Convert</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=new Date(+$('#v').value*1000).toString()},
 'age-calculator':()=>{A.innerHTML='<h2>Age Calculator</h2><input id="d" class="input" type="date"><button class="btn" id="go">Calculate</button><div class="out" id="o"></div>';$('#go').onclick=()=>{const d=$('#d').value;if(!d)return;const b=new Date(d),n=new Date();let age=n.getFullYear()-b.getFullYear();if(n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))age--;$('#o').textContent=age+' years'}},
 'percentage-calculator':()=>{A.innerHTML='<h2>Percentage Calculator</h2><div class="row"><input id="a" class="input" type="number" placeholder="Percentage"><input id="b" class="input" type="number" placeholder="Number"></div><button class="btn" id="go">Calculate</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=((+$('#a').value*+$('#b').value)/100).toFixed(2)},
 'bmi-calculator':()=>{A.innerHTML='<h2>BMI Calculator</h2><div class="row"><input id="w" class="input" type="number" placeholder="Weight kg"><input id="h" class="input" type="number" placeholder="Height cm"></div><button class="btn" id="go">Calculate</button><div class="out" id="o"></div>';$('#go').onclick=()=>{const h=+$('#h').value/100;$('#o').textContent=(+$('#w').value/(h*h)).toFixed(2)}},
 'unit-converter':()=>{A.innerHTML='<h2>Unit Converter</h2><input id="v" class="input" type="number" value="1"><div class="row"><select id="f"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select><select id="t"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select></div><button class="btn" id="go">Convert</button><div class="out" id="o"></div>';$('#go').onclick=()=>{const z={m:1,km:1000,ft:.3048,mi:1609.344,kg:1,lb:.453592};$('#o').textContent=((+$('#v').value*z[$('#f').value])/z[$('#t').value]).toFixed(6)+' '+$('#t').value}},
 'lorem-ipsum-generator':()=>{A.innerHTML='<h2>Lorem Ipsum Generator</h2><input id="n" class="input" type="number" value="3" min="1" max="20"><button class="btn" id="go">Generate</button><textarea id="o"></textarea>';$('#go').onclick=()=>$('#o').value=Array.from({length:+$('#n').value},()=> 'Lorem ipsum dolor sit amet, consectetur adipiscing elit.').join('\n\n')}
