function simple(fn){A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES,'UTF-8')?></h2><textarea id="i" placeholder="Enter text..."></textarea><button class="btn" id="go">Process</button><button class="btn alt" id="cp">Copy</button><div class="out" id="o"></div>';$('#go').onclick=()=>{try{$('#o').textContent=fn($('#i').value)}catch(e){$('#o').textContent='Invalid input: '+e.message}};$('#cp').onclick=()=>navigator.clipboard?.writeText($('#o').textContent)}
